WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")}

try{

    var LeadToUpdate = new sforce.SObject("Lead");

    LeadToUpdate.Id = "{!Lead.Id}";
    LeadToUpdate.isSendEmailGDPR__c = true;
    LeadToUpdate.Data_invio_GDPR__c = null;
                LeadToUpdate.Data_risposta_GDPR__c = null;
                LeadToUpdate.privacy__c = null;
                LeadToUpdate.HasOptedOutOfEmail = false;

    var result = sforce.connection.update([LeadToUpdate]);

    if(result[0].success === "true"){
        location.reload();
    }
    else{
        alert("An Error has Occurred. Error: " + result[0].errors.message);
    }
}
catch(e){
    alert("An unexpected Error has Occurred. Error: " + e);
}
